const analyticsRetention = `-- name: AnalyticsRetention :many
WITH c AS (
    SELECT u.id, (u.created_at AT TIME ZONE 'Asia/Shanghai')::date AS signup_date
    FROM users u LEFT JOIN user_platform p ON p.user_id = u.id
    WHERE (u.created_at AT TIME ZONE 'Asia/Shanghai')::date BETWEEN $2::date AND $3::date
      AND ($4::text IS NULL OR p.platform = $4)
), x AS (
    SELECT c.id, c.signup_date, date_trunc('week', c.signup_date)::date AS week,
        array(SELECT a.date - c.signup_date FROM user_daily_activity a
              WHERE a.user_id = c.id AND a.date BETWEEN c.signup_date + 1 AND c.signup_date + 31)::int[] AS days
    FROM c
)
SELECT week,
    count(*)::int AS users,
    count(*) FILTER (WHERE signup_date + 1 < $1::date)::int AS d1_eligible,
    count(*) FILTER (WHERE signup_date + 1 < $1::date AND 1 = ANY(days))::int AS d1,
    count(*) FILTER (WHERE signup_date + 3 < $1::date)::int AS d3_eligible,
    count(*) FILTER (WHERE signup_date + 3 < $1::date AND 3 = ANY(days))::int AS d3,
    count(*) FILTER (WHERE signup_date + 7 < $1::date)::int AS d7_eligible,
    count(*) FILTER (WHERE signup_date + 7 < $1::date AND 7 = ANY(days))::int AS d7,
    count(*) FILTER (WHERE signup_date + 14 < $1::date)::int AS d14_eligible,
    count(*) FILTER (WHERE signup_date + 14 < $1::date AND 14 = ANY(days))::int AS d14,
    count(*) FILTER (WHERE signup_date + 31 < $1::date)::int AS d30_eligible,
    count(*) FILTER (WHERE signup_date + 31 < $1::date AND days && ARRAY[29, 30, 31])::int AS d30
FROM x GROUP BY week ORDER BY week
`

type AnalyticsRetentionParams struct {
	Today    time.Time
	FromDate time.Time
	ToDate   time.Time
	Platform *string
}

type AnalyticsRetentionRow struct {
	Week        time.Time
	Users       int32
	D1Eligible  int32
	D1          int32
	D3Eligible  int32
	D3          int32
	D7Eligible  int32
	D7          int32
	D14Eligible int32
	D14         int32
	D30Eligible int32
	D30         int32
}

// Weekly sign-up cohorts (weeks start Monday). dN = opened the App exactly N days after
// sign-up; d30 = on any of days 29–31 (gate B). *_eligible counts users whose day is over.
func (q *Queries) AnalyticsRetention(ctx context.Context, arg AnalyticsRetentionParams) ([]AnalyticsRetentionRow, error) {
	rows, err := q.db.Query(ctx, analyticsRetention,
		arg.Today,
		arg.FromDate,
		arg.ToDate,
		arg.Platform,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AnalyticsRetentionRow{}
	for rows.Next() {
		var i AnalyticsRetentionRow
		if err := rows.Scan(
			&i.Week,
			&i.Users,
			&i.D1Eligible,
			&i.D1,
			&i.D3Eligible,
			&i.D3,
			&i.D7Eligible,
			&i.D7,
			&i.D14Eligible,
			&i.D14,
			&i.D30Eligible,
			&i.D30,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

